final class Machine {
    private let lock = NSLock()
    private var state = State.idle        // guarded by lock

    func tryStart() -> Bool {
        guard lock.try() else { return false }      // balk: transition in flight
        defer { lock.unlock() }
        guard state == .idle else { return false }  // balk: state forbids it
        state = .running
        return true
    }
}
